    /// Add a function to the interface definition.
    fn add_function(
        &mut self,
        attrs: &[syn::Attribute],
        name: &syn_solidity::SolIdent,
        purity: Purity,
        params: FunctionParameters,
        return_type: syn::Type,
    ) {
        let rust_name = syn::Ident::new(&name.to_string().to_case(Case::Snake), name.span());

